import { defineConfig, devices } from '@playwright/test'

// Visual baselines are Linux-only. Playwright picks a snapshot by platform, so
// the committed files end in `-linux.png`; a macOS baseline never satisfies a
// Linux run because font rasterisation and subpixel rounding differ. Baselines
// are generated by `.github/workflows/visual-baselines.yml`, never by
// `--update-snapshots` on a developer machine.
const port = Number(process.env.E2E_PORT ?? 4110)

// `E2E_BASE_URL` runs the suite against an already-served app and skips the
// `webServer` block.
const externalBaseURL = process.env.E2E_BASE_URL

const baseURL = externalBaseURL ?? `http://127.0.0.1:${port}`

export default defineConfig({
  testDir: './e2e-visual',
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  // A retried visual diff either hides a real regression or doubles the noise.
  // Fail on the first mismatch and read the diff artifact instead.
  retries: 0,
  reporter: [['list'], ['html', { open: 'never', outputFolder: 'playwright-report-visual' }]],
  outputDir: './test-results-visual',
  snapshotPathTemplate: '{testDir}/__screenshots__/{testFileName}/{arg}-{projectName}-{platform}{ext}',
  expect: {
    toHaveScreenshot: {
      animations: 'disabled',
      caret: 'hide',
      scale: 'css',
      // 1% of pixels may differ by up to 20% luminance: enough to absorb
      // antialiasing on text and borders, too little to hide a shifted layout.
      threshold: 0.2,
      maxDiffPixelRatio: 0.01,
    },
  },
  use: {
    baseURL,
    testIdAttribute: 'data-testid',
    colorScheme: 'light',
    reducedMotion: 'reduce',
    locale: 'en-US',
    timezoneId: 'UTC',
    deviceScaleFactor: 1,
    // No traces: the diff image is the artifact that explains a visual failure,
    // and a trace zip written into a mounted volume under parallel workers hits
    // filesystem contention that has nothing to do with the layout.
    trace: 'off',
    screenshot: 'only-on-failure',
    video: 'off',
  },
  webServer: externalBaseURL
    ? undefined
    : {
        // The static build is pinned instead of inheriting `.env`, because the
        // baselines must not depend on a developer's local API host. The API base
        // must be a *closed port*: an empty value makes the app's `/v/**` calls
        // loop back into its own prerender (`Loop detected while prerendering`),
        // which stalls the build and leaves `.output/public` without assets.
        command: [
          'API_BASE_URL=http://127.0.0.1:9 API_VERSION=1 ASSET_HOST= NUXT_PUBLIC_CATEGORY_IDENTITY_CONTRACT_VERSION=2 pnpm e2e:serve',
          `pnpm exec serve .output/public --listen tcp://127.0.0.1:${port}`,
        ].join(' && '),
        url: baseURL,
        timeout: 240_000,
        // Always rebuild: reusing whatever answered on the port would compare
        // against an output built with a different API base.
        reuseExistingServer: false,
      },
  projects: [
    {
      name: 'chromium',
      use: {
        ...devices['Desktop Chrome'],
      },
    },
  ],
})
